SPECIFICATION:

I would like you to implement a module named TopModule with the following
interface. All input and output ports are one bit unless otherwise
specified.

 - input  clk
 - input  reset
 - input  data
 - output start_shifting

The module should implement a finite-state machine that searches for the
sequence 1101 in an input bit stream. When the sequence is found, it
should set start_shifting to 1, forever, until reset. Reset is active
high synchronous. Assume all sequential logic is triggered on the
positive edge of the clock.



CANDIDATE RTL TO ATTACK:
```verilog
module TopModule (
    input  wire clk,
    input  wire reset,
    input  wire data,
    output reg  start_shifting
);

    // State encoding for FSM looking for "1101"
    // S_IDLE: no match yet (or just looking for first '1')
    // S_1:    saw "1"
    // S_11:   saw "11"
    // S_110:  saw "110"
    // S_DONE: saw "1101", holds start_shifting high forever
    parameter S_IDLE = 3'b000;
    parameter S_1    = 3'b001;
    parameter S_11   = 3'b010;
    parameter S_110  = 3'b011;
    parameter S_DONE = 3'b100;

    reg [2:0] current_state, next_state;

    // Sequential state update
    always @(posedge clk) begin
        if (reset) begin
            current_state  <= S_IDLE;
            start_shifting <= 1'b0;
        end else begin
            current_state <= next_state;
            if (next_state == S_DONE) begin
                start_shifting <= 1'b1;
            end
        end
    end

    // Combinational next-state and output logic
    always @(*) begin
        next_state = current_state;

        case (current_state)
            S_IDLE: begin
                if (data)
                    next_state = S_1;
                else
                    next_state = S_IDLE;
            end

            S_1: begin
                if (data)
                    next_state = S_11;
                else
                    next_state = S_IDLE;
            end

            S_11: begin
                if (data)
                    next_state = S_11;   // overlapping sequence handling: "111" leads to "11"
                else
                    next_state = S_110;
            end

            S_110: begin
                if (data)
                    next_state = S_DONE;
                else
                    next_state = S_IDLE;
            end

            S_DONE: begin
                next_state = S_DONE;
            end

            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

endmodule
```

